import ColorWheelIndicator from './ColorWheelIndicator';
import './wheel.css';

// Static artwork is generated by scripts/regen-wheel.js.
// The old 420 aliases use the same scalable SVGs instead of requesting
// assets that the generator does not produce.
const BASES = {
  labels: '/wheels/wheel-300-labels.svg',
  'labels-degrees': '/wheels/wheel-300-labels-degrees.svg',
  'labels-420': '/wheels/wheel-300-labels.svg',
  'labels-degrees-420': '/wheels/wheel-300-labels-degrees.svg',
};

const WHEEL_CENTER = 150;
// The generated wheel has a 420x420 viewBox, with its 300-unit wheel
// centered inside a 60-unit margin. Maintain the existing indicator radius.
const WHEEL_RADIUS = 300 * (142.5 / 420);

export default function ColorWheel300({
  currentColor,
  children,
  base = 'labels',
  staticBase = true, // retained for backwards-compatible callers
  size = 300,
}) {
  const hue = currentColor?.hcl_h == null ? NaN : Number(currentColor.hcl_h);
  const hasHue = Number.isFinite(hue);
  const baseSrc = BASES[base] || BASES.labels;

  return (
    <div
      className="wheel300-stack"
      aria-label="HCL Color Wheel"
      style={{ '--wheel-size': `${size}px` }}
    >
      <img className="wheel300-base" src={baseSrc} alt="HCL Color Wheel" />
      <svg
        id="wheel300"
        className="wheel300-overlay"
        height={300}
        width={300}
        viewBox="0 0 300 300"
        aria-hidden="true"
      >
        {hasHue && (
          <ColorWheelIndicator
            hue={((hue % 360) + 360) % 360}
            center={WHEEL_CENTER}
            radius={WHEEL_RADIUS}
            strokeColor="black"
          />
        )}
        {children}
      </svg>
    </div>
  );
}
